  window.addEventListener("dma-sprachaufnahme", function (ev) {
    KLANG.stillAufnahme = Boolean(ev && ev.detail && ev.detail.an);
    stilleSetzen();
  });
  window.addEventListener("dma-selbst-spricht", function (ev) {
    KLANG.stillSprechen = Boolean(ev && ev.detail && ev.detail.an);
    stilleSetzen();
  });
  function toeneAn() { try { var b = B(); return b.toeneAn ? b.toeneAn() !== false : true; } catch (e) { return true; } }
  function klangSpielen(name, laut, tempo) {
    var k = KLANG.ctx, p = KLANG.puffer[name];
    if (!k || !p || k.state !== "running") return false;
    try {
      var g = k.createGain(), q = k.createBufferSource();
      var redet = false; try { redet = Boolean(LC() && LC().redetJemand && LC().redetJemand()); } catch (e) {}
      g.gain.value = Math.max(0, Math.min(1, (laut == null ? 0.5 : laut) * (redet ? 0.45 : 1)));
      q.buffer = p;
      /* Fassung 695: Tierstimmen klingen nie zweimal gleich (etwas höher/tiefer). */
      if (tempo && tempo !== 1) try { q.playbackRate.value = tempo; } catch (e) {}
      q.connect(g); g.connect(KLANG.master || k.destination); q.start(0);
      KLANG.gespielt++; KLANG.letzter = name;
      return true;
    } catch (e) { KLANG.fehler = String(e && e.message || e); return false; }
  }
  function ton(name, laut) {
    if (!name || !toeneAn() || lautStufe() === 0) return;
    /* FASSUNG 652 — wer nicht mitspielt, hört das Spiel nicht. */
    /* (Ausnahme: man bedient gerade selbst das Spielmenü.) */
    if (!spielSichtbar() && !S.chatTonFrei && !S.schnellMenue && !(panel && !panel.hidden)) return;
    if (klangSpielen(name, laut)) { try { if (window.DMA_TONLOG) window.DMA_TONLOG.push({ name: name, wann: Math.round(performance.now()), weg: "webaudio" }); } catch (e) {} return; }
    /* Noch nicht geladen oder nicht frei: diesmal der alte Weg, für das
       nächste Mal wird geladen. */
    KLANG.ersatz++;
    klangLaden(name);
    try { if (B().ton) B().ton(name, (laut == null ? 0.5 : laut) * lautFaktor()); } catch (e) {}
  }
  /* FASSUNG 645 — Meldungen des Spiels. XANDER: „ich kann ja nicht mal
     auf Laden und Schutz drücken aus diesem Android Menü raus". Die
     App-Blasen (Toasts) lagen fest unten über dem Menü, ganz oben in
     der Ebene, und fingen jeden Tipp ab. Das Spiel meldet sich jetzt in
     einer eigenen, durchklickbaren Zeile über der Leiste. */
  var meldungEl = null, meldungUhr = 0;
  function hinweis(text) {
    try { console.log("[Spiel]", text); } catch (e) {}
    try { if (window.__spielMeldungen) window.__spielMeldungen.push(String(text)); } catch (e) {}
    /* FASSUNG 833 — im Vollbild der neuen Stadt steht die Meldung oben in deren Rahmen (das Menü liegt dahinter) */
    try { if (typeof LSTADT !== "undefined" && LSTADT && LSTADT.voll) lsMeldung(text); } catch (e) {}
    /* FASSUNG 669 — läuft ein Extra-Spiel, steht die Meldung im Spielfenster. */
    if (typeof extraEl !== "undefined" && extraEl && extraEl.isConnected) {
      var em = extraEl.querySelector(".sp-extra-meldung");
      if (!em) { em = document.createElement("div"); em.className = "sp-extra-meldung"; em.setAttribute("role", "status"); extraEl.insertBefore(em, extraEl.children[1] || null); }
      em.textContent = String(text || ""); em.classList.remove("sp-weg"); void em.offsetWidth;
      clearTimeout(em.uhr); em.uhr = setTimeout(function () { em.classList.add("sp-weg"); }, 3200);
      return;
    }
    var form = document.getElementById("lcForm");
    if (!form || !form.parentNode || !drin()) { try { if (B().toast) B().toast(text); } catch (e) {} return; }
    /* Menü offen: die Meldung steht in seiner Kopfzeile, nicht auf den Knöpfen. */
    if (S.schnellMenue && schnellEl && schnellEl.querySelector(".sp-sm-kopf")) {
      S.menueMeldung = { text: String(text || ""), bis: Date.now() + 3800 };
      if (meldungEl) meldungEl.hidden = true;
      schnellZeichnen(true);
      clearTimeout(meldungUhr);
      meldungUhr = setTimeout(function () { schnellZeichnen(); }, 3900);
      return;
    }
    if (!meldungEl || !meldungEl.isConnected) {
      meldungEl = document.createElement("div");
      meldungEl.className = "sp-meldung";
      meldungEl.setAttribute("role", "status");
      form.parentNode.insertBefore(meldungEl, form);
    }
    meldungEl.textContent = String(text || "");
    meldungEl.classList.remove("sp-meldung-weg");
    meldungEl.hidden = false;
    meldungSetzen();
    clearTimeout(meldungUhr);
    meldungUhr = setTimeout(function () { if (meldungEl) meldungEl.classList.add("sp-meldung-weg"); }, 3800);
  }
  /* Die Zeile sitzt über der Leiste (und über dem offenen Menü). */
  function meldungSetzen() {
    if (!meldungEl || meldungEl.hidden) return;
    var unten = 60;
    try {
      if (schnellEl && !schnellEl.hidden) {
        unten = (parseFloat(schnellEl.style.bottom) || 0) + schnellEl.offsetHeight + 6 + (schnellEl.querySelector(".sp-s-burger") ? 36 : 0);
        /* FASSUNG 650 — ein offenes Rad (Waffen oder Zauber) steht über
           der Leiste: die Meldung rückt darüber, statt es zu verdecken. */
        var radOffen = schnellEl.querySelector(".sp-rad");
        if (radOffen) unten += radOffen.offsetHeight + 6;
      }
      else { var f = document.getElementById("lcForm"); unten = f.parentNode.clientHeight - f.offsetTop + 6; }
    } catch (e) {}
    meldungEl.style.bottom = Math.round(unten) + "px";
  }
  /* FASSUNG 652 — XANDER: „bist du dir sicher, dass die anderen normalen
     Chat Teilnehmer die spielenden nicht sehen … Das wäre mir noch sehr
     wichtig, dass das wirklich so intern ist … wie mit den
     Sprachnachrichten". Das Spiel ist nur für die da, die mitspielen:
     Ringe, Mauern, Tiere, Schüsse, Zauber und Töne sieht und hört nur,
     wer selbst „Mitspielen" an hat. */
  function spielSichtbar() { return Boolean(S.bereit && S.ich && S.ich.mitspielen); }
  function drin() { var l = LC(); try { return Boolean(l && l.lage && l.lage().lage === "drin"); } catch (e) { return false; } }

  /* ---------------------------------------------------------------
     ANMELDUNG: Konto (auth.uid) oder anonyme Gastsitzung
     --------------------------------------------------------------- */
  /* backend.js beginnt mit „const Backend = …" — das ist ein globaler
     Name, aber KEINE Eigenschaft von window. window.Backend war hier
     also immer leer: jeder Angemeldete galt als Gast, und der Betreiber
     wurde nie erkannt (gefunden bei Funk 102, dieselbe Falle wie beim
     Sprechbild: „DAS BACKEND HEISST BACKEND — NICHT window.Backend"). */
  function BE() {
    try { if (typeof Backend !== "undefined" && Backend) return Backend; } catch (e) {}
    return window.Backend || null;
  }
  function klientHolen() {
    if (S.klient) return Promise.resolve(S.klient);
    var be = BE();
    var angemeldet = false;
    try { angemeldet = Boolean(be && be.currentUser && be.currentUser() && be.currentUser().id); } catch (e) {}
    if (angemeldet && be.zugang && be.zugang()) {
      S.klient = be.zugang();
      return Promise.resolve(S.klient);
    }
    if (!window.supabase || !window.SUPABASE_CONFIG) return Promise.reject(new Error("keine Verbindung"));
    /* Eigener Speicherplatz für die Gastsitzung — sonst hielte sich die
       Konto-Anmeldung der Seite (backend.js) plötzlich für angemeldet. */
    var k = window.supabase.createClient(window.SUPABASE_CONFIG.url, window.SUPABASE_CONFIG.anonKey,
      { auth: { storageKey: "dma-spiel-gast", persistSession: true, autoRefreshToken: true } });
    return k.auth.getSession().then(function (a) {
      if (a && a.data && a.data.session) return k;
      return k.auth.signInAnonymously().then(function (r) {
        if (r && r.error) throw r.error;
        return k;
      });
    }).then(function (kk) { S.klient = kk; S.gast = true; return kk; });
  }
  /* FUNK 104 — XANDER: „da ist als Information dass ich mich mit meinem
     Konto einloggen soll obwohl ich schon eingeloggt bin".
     Das Spiel trat beim Öffnen der Seite bei, oft BEVOR die Anmeldung
     wiederhergestellt war — dann galt man als Gast, bekam den
     Anmelde-Hinweis und wartete 30 s bis zum nächsten Versuch. Sobald
     die Anmeldung da ist, ruft app.js hier an: neuer Versuch, sofort,
     mit dem Konto. */
  function anmeldungDa() {
    if (S.bereit && !S.gast) return;
    if (S.gast) { S.klient = null; S.gast = false; S.bereit = false; }
    S.versucht = false; S.naechsterVersuch = 0; S.fehler = "";
    try { if (drin()) beitreten(); } catch (e) {}
    panelAuffrischen();
  }

  function rpc(name, args) {
    return klientHolen().then(function (k) { return k.rpc(name, args || {}); }).then(function (r) {
      if (r && r.error) throw r.error;
      return r ? r.data : null;
    });
  }

  function beitreten() {
    if (S.bereit || S.versucht) return;
    /* Nach einem Fehlschlag erst nach 30 s wieder versuchen. */
    if (S.naechsterVersuch && Date.now() < S.naechsterVersuch) return;
    S.versucht = true;
    var l = LC(); var name = "";
    try { name = l.lage().ichName || ""; } catch (e) {}
    rpc("spiel_ich", { p_name: name }).then(function (ich) {
      S.ich = ich; S.uid = ich && ich.id; S.bereit = true; S.fehler = "";
      if (S.uid) S.stand[S.uid] = ich;
      try { if (l.spielKennungSetzen) l.spielKennungSetzen(S.uid); } catch (e) {}
      senden({ ereignis: "stand", stand: oeffentlich(ich) });
      abrufen(true);
      einspielenWennBetreiber();
      geschenkePruefen();
      zeichnen();
    }).catch(function (e) {
      S.versucht = false;
      S.naechsterVersuch = Date.now() + 30000;
      /* Ohne Konto geht es nur, wenn in Supabase die anonyme Anmeldung
         eingeschaltet ist (Stand 24.09.: aus — 0 anonyme Nutzer). */
      S.fehler = BE() && BE().currentUser && BE().currentUser()
        ? "Das Spiel ist gerade nicht erreichbar – gleich noch mal."
        : "Zum Mitspielen bitte mit deinem Konto anmelden – Punkte und Lebenspunkte gehören zu deinem Konto.";
      panelAuffrischen();
      try { console.warn("[Spiel] Beitritt ging nicht:", e && e.message ? e.message : e); } catch (x) {}
    });
  }
  function oeffentlich(s) {
    if (!s) return null;
    var o = {};
    ["id", "name", "lp", "lp_max", "kaputt", "schild", "mauer_art", "mauer_lp", "haustier",
     "geschuetz", "wischer", "anfaenger", "verdient", "mana", "mana_max", "kraft", "ziel", "tempo",
     "haustier_leben", "geschuetz_stufe", "eisen", "tarn", "mitspielen",
     "level", "skills", "helm", "brust", "ladung", "daemon",
     "haustier_stufe", "haustier_max", "flugtier", "flugtier_leben", "flugtier_stufe", "flugtier_max", "mauer_aufbau", "zeigen", "klasse", "graben", "turm_platz", "turm_raum", "dorf", "nebel_s", "wackel_s", "brezel_s", "hexe_s", "zwerg_s", "formular_s", "kampfklasse", "kampf_stufe", "dorf_name", "dorf_plan", "baustellen", "haft", "gefangene", "wahrzeichen"].forEach(function (k) { o[k] = s[k]; });
    return o;
  }

  /* ---------------------------------------------------------------
     WER SITZT WO — Chat-Kennung ↔ Spiel-Kennung
     --------------------------------------------------------------- */
  function plaetze() { try { return LC().lage().plaetze || []; } catch (e) { return []; } }
  function spielIdVon(chatId) {
    if (!chatId) return "";
    if (istPuppe(chatId)) { puppeStand(chatId); return "puppe:" + chatId; }
    var l = LC();
    try {
      if (chatId === l.lage().ichId) return S.uid;
      return (l.spielIdVon && l.spielIdVon(chatId)) || "";
    } catch (e) { return ""; }
  }
  function platzElVon(chatId) {
    /* XANDER (25.09.): „kannst du mir vielleicht nur ein Sparringspartner
       machen, mit dem ich trainieren kann" — der Sparringspartner steht
       über einem FREIEN Platz, nur auf dem eigenen Gerät. Er ist kein
       Mensch im Raum und belegt keinen Sitz. */
    var sp = /^sparring:(\d+)$/.exec(String(chatId || ""));
    if (sp) return document.querySelector('#lcPlaetze .lc-platz[data-lc-platz="' + sp[1] + '"]');
    return document.querySelector('#lcPlaetze .lc-platz[data-lc-id="' + String(chatId).replace(/"/g, "") + '"]');
  }

  /* Alle 12 s den Stand aller Sitzenden holen (Selbstheilung läuft auf
     dem Server mit). */
  function abrufen(sofort) {
    if (!S.bereit) return;
    var jetzt = Date.now();
    if (!sofort && jetzt - S.letzterAbruf < 12000) return;
    S.letzterAbruf = jetzt;
    var ids = [];
    plaetze().forEach(function (p) {
      if (p.leer || istPuppe(p.id)) return;     /* FUNK 100: die Puppe hat kein Konto */
      var sid = spielIdVon(p.id);
      if (sid && ids.indexOf(sid) < 0) ids.push(sid);
    });
    if (S.uid && ids.indexOf(S.uid) < 0) ids.push(S.uid);
    rpc("spiel_stand", { p_ids: ids }).then(function (liste) {
      (liste || []).forEach(function (s) {
        /* FASSUNG 683 — XANDER: „diese kleinen Zahlen, die Gesundheitspunkte, wenn er einfach steht und
           nichts macht und sich regeneriert". Grüne Zahl und ein sanftes Leuchten am Bild. */
        var vorher = S.stand[s.id];
        if (vorher && !vorher.kaputt && !s.kaputt && s.lp > vorher.lp && spielSichtbar()) erholtZeigen(s, s.lp - vorher.lp);
        S.stand[s.id] = s;
      });
      return rpc("spiel_ich", { p_name: null });
    }).then(function (ich) {
      if (ich) { veraenderungMelden(S.ich, ich); S.ich = ich; S.stand[ich.id] = oeffentlich(ich); }
      zeichnen(); panelAuffrischen();
      fallenHolen();
      geschenkePruefen();
    }).catch(function () {});
  }
  /* Was sich still auf dem Server getan hat, sagen wir an:
     Training fertig, Helm oder Brustpanzer durchgeschlagen. */
  function veraenderungMelden(vorher, jetzt) {
    if (!vorher || !jetzt) return;
    if (vorher.training && !jetzt.training) {
      var sk = SKILLS.filter(function (x) { return x[0] === vorher.training.skill; })[0];
      hinweis("💪 Training fertig: " + (sk ? sk[1] : "Können") + " Stufe " + vorher.training.stufe + " – für immer.");
      ton("jubel", 0.45);
    }
    if (vorher.helm_halt > 0 && jetzt.helm_halt === 0 && jetzt.helm_stufe > 0) hinweis("⛑️ Dein Helm ist durch – Reparatur 10 Punkte (Schutz & Laden).");
    if (vorher.brust_halt > 0 && jetzt.brust_halt === 0 && jetzt.brust_stufe > 0) hinweis("🛡️ Dein Brustpanzer ist durch – Reparatur 10 Punkte (Schutz & Laden).");
  }
  /* XANDER: „tägliche Login … Geschenke" und „wenn man auf der Seite
     Aufgaben macht … 20 Bratwürste gewinnen … Coins".
     Das Tagesgeschenk holt sich selbst ab, sobald man im Klassenzimmer
     ist (einmal je Tag, Serie bis 7). Die Übungspunkte der Seite werden
     alle 5 Minuten umgetauscht: 5 Seitenpunkte = 1 Spielpunkt, höchstens
     40 am Tag; je 50 Seitenpunkte eine Bratwurst (höchstens 3). */
  function geschenkePruefen() {
    if (!S.bereit || !S.ich || S.geschenkLaeuft) return;
    var jetzt = Date.now();
    var geschenk = Boolean(S.ich.geschenk_offen);
    var seite = !S.seiteZeit || jetzt - S.seiteZeit > 300000;
    if (!geschenk && !seite) return;
    S.geschenkLaeuft = true;
    var kette = Promise.resolve();
    /* Nur übernehmen, was wirklich ein ganzer Spielstand ist (mit id) —
       sonst würde eine leere Antwort den eigenen Stand überschreiben. */
    if (geschenk) kette = rpc("spiel_tagesgeschenk", {}).then(function (r) {
      if (!r || !r.ok || !r.id) return;
      S.ich = r; S.stand[r.id] = oeffentlich(r);
      ton("geschenk", 0.5);
      var gText = "Tagesgeschenk (Tag " + r.serie + " von 7): +" + r.punkte_plus + " Punkte, +" + r.bratwurst_plus + " Bratwurst"
        + (r.pflaster_plus ? ", +1 Pflaster" : "") + ", +20 Erfahrung";
      hinweis("🎁 " + gText);
      geschenkMelden(gText);
    });
    kette.then(function () {
      if (!seite) return null;
      S.seiteZeit = jetzt;
      return rpc("spiel_seite_abholen", {});
    }).then(function (r) {
      S.geschenkLaeuft = false;
      if (!r || !r.ok || !r.id) return;
      S.ich = r; S.stand[r.id] = oeffentlich(r);
      if (r.muenzen > 0 || r.bratwurst_plus > 0) {
        setTimeout(function () {
          hinweis("📚 Für deine Übungen auf der Seite: +" + r.muenzen + " Punkte" + (r.bratwurst_plus ? ", +" + r.bratwurst_plus + " Bratwurst" : ""));
        }, geschenk ? 3000 : 0);
      }
      zeichnen(); panelAuffrischen();
    }).catch(function () { S.geschenkLaeuft = false; });
  }
  /* FASSUNG 742 — XANDER (Walkie 273): „Wie sieht man das und wo findet man das wenn man die ganze Zeit z.B eingeloggt
     bleibt." Das Geschenk holt sich nach Mitternacht (Berliner Zeit) beim nächsten stillen Nachsehen von selbst ab – auch
     wer die ganze Nacht im Klassenzimmer bleibt. Damit man es nicht verpasst, steht es jetzt zusätzlich als Meldung oben
     im Band (bleibt, bis man sie wegtippt oder sie nach 8 s weiterläuft), und im Spiel-Menü steht, ob es heute schon
     abgeholt ist und wann das nächste kommt. */
  function geschenkMelden(text) {
    /* Der Tag zählt wie auf dem Server nach Berliner Zeit (sonst ginge zwischen 0 und 2 Uhr die Meldung verloren). */
    var key = "g:" + new Date().toLocaleDateString("sv-SE", { timeZone: "Europe/Berlin" });
    if (sprungGemeldet()[key]) return;
    sprungMerken(key);
    SPRUNG.liste.unshift({ key: key, art: "fertig", bild: GESCHENK_SVG, ohneSprung: true, text: text });
    if (!SPRUNG.el || !SPRUNG.el.isConnected) sprungZeigen();
  }
  var GESCHENK_SVG = '<svg viewBox="0 0 20 20"><rect x="3" y="8" width="14" height="9" rx="1.2" fill="#d8413a"/><rect x="2.2" y="5.6" width="15.6" height="3.4" rx="1" fill="#e85a4f"/>'
    + '<rect x="8.9" y="5.6" width="2.2" height="11.4" fill="#f2c230"/><path d="M10 5.6 C7 1.6 3.6 3.4 6.2 5.6 Z M10 5.6 C13 1.6 16.4 3.4 13.8 5.6 Z" fill="#f2c230"/></svg>';
  function geschenkZeile(ich) {
    if (ich.geschenk_offen) return "<span>🎁 Tagesgeschenk kommt gleich</span>";
    if (!(ich.tag_serie > 0)) return "";
    var jetzt = new Date(), berlin = new Date(jetzt.toLocaleString("en-US", { timeZone: "Europe/Berlin" }));
    var bisMitternacht = (24 * 60 - berlin.getHours() * 60 - berlin.getMinutes()), h = Math.floor(bisMitternacht / 60), m = bisMitternacht % 60;
    return "<span title=\"Holt sich nach Mitternacht von selbst ab – auch wenn du eingeloggt bleibst.\">🎁 Heute abgeholt · Tag " + ich.tag_serie + "/7 · nächstes in "
      + (h ? h + " h " : "") + m + " min</span>";
  }
  /* XANDER: „Superkraft … dämonisch aufgeladen". Die goldene Ladung
     oben am Bild füllt sich mit Deutsch (+8), Treffern (+2) und
     Einstecken (+3). Voll: 45 s ×1,5 Schaden, nur 70 % einstecken. */
  function superkraft() {
    rpc("spiel_superkraft", {}).then(function (r) {
      if (!r || !r.ok) { hinweis("🔥 " + ((r && r.grund) || "geht nicht")); return; }
      S.ich = r; S.stand[r.id] = oeffentlich(r);
      senden({ ereignis: "stand", stand: oeffentlich(r) });
      senden({ ereignis: "daemon" });
      daemonAusbruch(meineChatId(), true);
      zeichnen(); schnellZeichnen(); panelAuffrischen();
    }).catch(function (e) { hinweis("Superkraft ging nicht: " + (e && e.message ? e.message : e)); });
  }
  /* FASSUNG 655 — XANDER: „wo meine Superkraft aufgeladen ist, hat sich
     nicht das Gefühl, dass irgendwas passiert … da müsste eine andere
     Animation kommen, dass man das fühlt". Der Ausbruch: eine lila Welle
     vom eigenen Bild, der Bildschirmrand glüht lila, Flammen lodern um
     das Bild, so lange es wirkt; jeder Treffer zeigt eine große lila
     Zahl mit „×1,5". */
  function daemonAusbruch(chatId, ich) {
    ton("gong", 0.5); setTimeout(function () { ton("explosion2", 0.3); }, 180);
    var m = mittelpunkt(chatId);
    if (m) {
      [0, 260].forEach(function (warte) {
        setTimeout(function () {
          var w = document.createElement("div");
          w.className = "sp-daemon-welle";
          w.style.left = m.x + "px"; w.style.top = m.y + "px"; w.style.width = w.style.height = Math.round(m.r * 2) + "px";
          document.body.appendChild(w);
          setTimeout(function () { w.remove(); }, 1300);
        }, warte);
      });
    }
    if (ich) {
      var schirm = document.createElement("div");
      schirm.className = "sp-daemon-schirm";
      document.body.appendChild(schirm);
      setTimeout(function () { schirm.remove(); }, 1800);
      hinweis("🔥 Dämonisch! 90 s lang: du teilst ×1,5 Schaden aus und steckst nur 70 % ein.");
    }
    zahlZeigen(chatId, null, "dämonisch");
  }
  function trainieren(skill) {
    rpc("spiel_trainieren", { p_skill: skill }).then(function (r) {
      if (!r || !r.ok) { hinweis("💪 " + ((r && r.grund) || "geht nicht")); return; }
      S.ich = r; S.stand[r.id] = oeffentlich(r);
      ton("kasse", 0.4);
      var sk = SKILLS.filter(function (x) { return x[0] === skill; })[0];
      hinweis("💪 Training läuft: " + (sk ? sk[1] : skill) + " – " + (5 * ((r.training && r.training.stufe) || 1)) + " Minuten. Spiel ruhig weiter.");
      panelAuffrischen();
    }).catch(function (e) { hinweis("Training ging nicht: " + (e && e.message ? e.message : e)); });
  }

  /* ---------------------------------------------------------------
     FUNK 100 — ÜBEN MIT DER PUPPE
     ---------------------------------------------------------------
     XANDER: „kann ich das mit dem Dummy testen wenn ich ihn irgendwo
     hin treffe oder das ja zufällig Punkte so an meinem Profilbild
     aussucht wo er mir hinschießt dass ich sehen kann ob das
     funktioniert."
     Die Übungspuppen (/puppe) sitzen nur auf dem eigenen Gerät und
     haben kein Konto. Deshalb rechnet hier der Browser, mit genau den
     Regeln des Servers (spiel_zone, spiel_faktor, spiel_waffe_schaden):
       · Treffer auf die Puppe: Zone, rote Zahl, Lebensbalken, kaputt;
         nach 4 s klebt sie sich ein Pflaster drauf.
       · Übungsduell (Reiter „Duell", Knopf bei der Puppe): die Puppe
         schießt alle paar Sekunden zurück, auf einen ZUFÄLLIGEN Punkt
         deines Bildes. Deine Lebenspunkte zählen nur in der Übung —
         in der Datenbank ändert sich nichts, Punkte gibt es keine.
     --------------------------------------------------------------- */
  function istPuppe(chatId) { return /^(uebungspuppe2?|sparring:\d+)$/.test(String(chatId || "")); }
  function puppeStand(chatId) {
    var sid = "puppe:" + chatId;
    if (!S.stand[sid]) {
      S.stand[sid] = { id: sid, name: chatId === "uebungspuppe2" ? "Dummy" : /^sparring/.test(chatId) ? "Sparring" : "Puppe", lp: 100, lp_max: 100,
                       kaputt: false, schild: 0, mauer_art: null, mauer_lp: 0,
                       haustier: chatId === "uebungspuppe" ? "fellmonster" : null,
                       geschuetz: chatId === "uebungspuppe2", wischer: 0, anfaenger: false, verdient: 0, uebung: true };
    }
    return S.stand[sid];
  }
  function zoneRechnen(dx, dy) {
    var d = Math.hypot(dx, dy);
    if (d > 1) return "daneben";
    if (Math.hypot(dx, dy + 0.3) <= 0.3) return "kopf";
    if (Math.hypot(dx - 0.18, dy - 0.35) <= 0.2) return "herz";
    return d <= 0.7 ? "koerper" : "streif";
  }
  var FAKTOR = { kopf: 2.0, herz: 1.6, koerper: 1.0, streif: 0.5, daneben: 0 };
  function schadenRechnen(waffe, zone) {
    return Math.round(((WAFFEN[waffe] || WAFFEN.bogen).schaden) * (FAKTOR[zone] || 0));
  }
  function puppeGetroffen(p, waffe, dx, dy) {
    var st = puppeStand(p.id);
    if (st.kaputt) { zahlZeigen(p.id, null, "schon kaputt"); return; }
    var zone = zoneRechnen(dx, dy), schaden = schadenRechnen(waffe, zone);
    st.lp = Math.max(0, st.lp - schaden);
    st.kaputt = st.lp <= 0;
    trefferZeigen(p.id, { zone: zone, schaden: schaden, abgewehrt: 0, kaputt: st.kaputt });
    /* FUNK 109/110 — Gegenwehr zum Ausprobieren: die Puppe hat ein
       Fellmonster, der Dummy ein Geschütz. Gerechnet wie auf dem Server
       (spiel_treffer); die Lebenspunkte zählen nur im Übungsduell. */
    if (schaden > 0) {
      var gg = p.id === "uebungspuppe2" ? Math.max(2, Math.min(18, Math.round(schaden * 0.5))) : 0;
      var gt = p.id === "uebungspuppe" ? Math.max(2, Math.min(10, Math.round(schaden * 0.3))) : 0;
      var gw = Math.min(gg + gt, Math.max(2, Math.round(schaden * 0.8)));
      if (S.uebung) S.uebung.lp = Math.max(0, S.uebung.lp - gw);
      gegenwehrZeigen(p.id, meineChatId(), { gegenwehr: gw, gegen_geschuetz: gg, gegen_tier: gt, tier: gt ? "fellmonster" : "" });
    }
    if (!S.uebungGesagt) { S.uebungGesagt = true; hinweis("🧍 Übung mit " + st.name + " – zählt nicht, keine Punkte."); }
    if (st.kaputt) {
      if (S.duell && S.duell.uebung && S.duell.gegnerChat === p.id) {
        hinweis("🏆 Runde gewonnen – " + st.name + " steht gleich wieder auf.");
      }
      setTimeout(function () {
        st.lp = st.lp_max; st.kaputt = false;
        zahlZeigen(p.id, st.lp_max, "Pflaster");
        zeichnen();
      }, 4000);
    }
    zeichnen();
  }
  function meinPlatzNummer() {
    var ich = meineChatId(), n = null;
    plaetze().forEach(function (q) { if (q.id === ich) n = q.nummer; });
    return n;
  }
  function uebungStarten(chatId) {
    if (!istPuppe(chatId) || !platzElVon(chatId)) return false;
    var st = puppeStand(chatId);
    st.lp = st.lp_max; st.kaputt = false;
    var max = (S.ich && S.ich.lp_max) || 100;
    S.uebung = { lp: max, max: max };
    /* FASSUNG 641 — XANDER: „der Sparring Partner der schießt immer nur
       zurück wenn ich wieder neu auf … geht, das soll eingeloggt bleiben".
       Das Übungsduell läuft, bis man es ausschaltet (vorher: 3 Minuten). */
    S.duell = { id: "uebung", gegner: "puppe:" + chatId, gegnerChat: chatId, bis: Date.now() + 36e6, uebung: true };
    hinweis("⚔️ Übung mit " + st.name + ": sie schießt zurück, bis du es ausschaltest (Menü → Mehr). Deine Tiere und dein Turm wehren sich mit. Zählt nicht.");
    schliessen();
    puppeSchussPlanen();
    zeichnen();
    return true;
  }
  function uebungEnde() {
    if (S.duell && S.duell.uebung) S.duell = null;
    clearTimeout(S.puppeUhr);
    S.uebung = null;
    zeichnen();
    panelAuffrischen();
  }
  /* Die eigene Gegenwehr, lokal gerechnet wie spiel_treffer (für die Übung). */
  /* FASSUNG 698 — Mauer gegen Waffe (so rechnet spiel_mauer_faktor). */
  var MAUER_NAME = { holz: "Holzmauer", ziegel: "Ziegelmauer", stein: "Steinmauer", stahl: "Stahlmauer", titan: "Titanmauer", diamant: "Diamantmauer" };
  var MAUER_RAT = {
    holz: "Beil (Tomahawk), Laser und Sprengstoff machen sie schnell kaputt.",
    ziegel: "Sprengstoff (Bazooka, Kuckucksuhr) knackt Ziegel am besten.",
    stein: "Sprengstoff (Bazooka, Kuckucksuhr) knackt Stein am besten.",
    stahl: "Energiewaffen schneiden Stahl, Sprengstoff geht auch.",
    titan: "Titan knackt eine Energiewaffe — mit ★★★ aus dem Labor noch besser.",
    diamant: "Durch Diamant kommt nur eine Energiewaffe ★★★ (Chips aus dem Labor)."
  };
  function mauerHinweis(art, waffe, f) {
    var jetzt = Date.now();
    if (S.mauerHinweisBis && jetzt < S.mauerHinweisBis) return;
    S.mauerHinweisBis = jetzt + 20000;
    hinweis("🧱 " + (MAUER_NAME[art] || "Die Mauer") + " hält – " + ((WAFFEN[waffe] || {}).name || "diese Waffe") + " schafft nur " + Math.round(f * 100) + " %. " + (MAUER_RAT[art] || ""));
  }
  function eigeneGegenwehr(roh) {
    /* FASSUNG 697 — dieselben Tiere und Zahlen wie spiel_treffer. Vorher kannte die Übung nur
       Fellmonster, Stachelmonster, Chihuahua, Drache und Eule; Schäferhund, Einhorn, Dackel,
       Wolpertinger, Feuerfuchs, Phönix, Storch, Greif, Lindwurm, Regenbogendrache wehrten
       sich in der Übung schwächer als im echten Kampf. */
    var ich = S.ich || {}, tf = 1 + 0.1 * Number(((ich.skills || {}).tierfreund) || 0), ing = 1 + 0.1 * Number(((ich.skills || {}).ingenieur) || 0);
    var st = Math.max(1, Math.min(5, ich.geschuetz_stufe || 1)), gg = 0, gt = 0, gf = 0, heil = 0;
    var R = Math.round, anteil = function (min, max, f) { return Math.max(min, Math.min(max, R(roh * f))); };
    if ((ich.geschuetz_ladungen || 0) > 0) gg = Math.max(2, Math.min(st >= 5 ? 26 : st >= 4 ? 22 : 18, R(roh * (0.3 + 0.2 * Math.min(3, st)) * ing)));
    if (ich.haustier && ich.haustier_leben > 0) {
      var hst = ich.haustier_stufe || 1, plus = hst >= 2 ? 2 : 0, hs = 1 + 0.15 * (Math.max(1, Math.min(3, hst)) - 1);
      var b = ({
        drache: function () { return anteil(3, 16, 0.5); },
        stachelmonster: function () { return anteil(1, 8, 0.2); },
        chihuahua: function () { return anteil(2, 9, 0.25) + plus; },
        schaeferhund: function () { return anteil(3, 14, 0.35) + plus; },
        babyfuchs: function () { return anteil(1, 7, 0.2); },
        einhorn: function () { return anteil(3, 14, 0.35); },
        dackel: function () { return anteil(2, 9, 0.25) + plus; },
        wolpertinger: function () { return anteil(3, 16, 0.5) + plus; },
        feuerfuchs: function () { return anteil(3, 15, 0.45) + plus; }
      }[ich.haustier] || function () { return anteil(2, 10, 0.3); })();
      gt = R(b * hs * tf);
      if (ich.haustier === "fellmonster" && hst >= 2) heil = 3;
      if (ich.haustier === "einhorn" && hst >= 2) heil += 2;
    }
    if (ich.flugtier && ich.flugtier_leben > 0) {
      var fst = ich.flugtier_stufe || 1, fs = 1 + 0.15 * (Math.max(1, Math.min(3, fst)) - 1);
      var fb = ({
        drache: function () { return anteil(3, 16, 0.5) + (fst >= 2 ? 2 : 0); },
        phoenix: function () { return anteil(3, 15, 0.45); },
        storch: function () { return anteil(2, 12, 0.35); },
        lindwurm: function () { return anteil(4, 19, 0.6); },
        greif: function () { return anteil(3, 16, 0.5); },
        regenbogendrache: function () { return anteil(4, 18, 0.55); }
      }[ich.flugtier] || function () { return anteil(2, 8, 0.25); })();
      gf = R(fb * fs * tf);
      if (ich.flugtier === "phoenix" && fst >= 2) heil += 2;
      if (ich.flugtier === "regenbogendrache" && fst >= 2) heil += 3;
    }
    /* Höchstens vier Fünftel des angerichteten Schadens (auch bei 1 Schaden nicht mehr als 1). */
    var gesamt = Math.min(gg + gt + gf, Math.max(1, R(roh * 0.8)));
    if (!(gg + gt + gf) || !(roh > 0)) gesamt = 0;
    return { gegenwehr: gesamt, gegen_geschuetz: gg, gegen_tier: gt, tier: gt ? ich.haustier : "", gegen_flug: gf, flugtier: gf ? ich.flugtier : "", tier_heil: heil };
  }
  function puppeSchussPlanen() {
    clearTimeout(S.puppeUhr);
    S.puppeUhr = setTimeout(puppeSchiesst, 2600 + Math.floor(Math.random() * 1900));
  }
  function puppeSchiesst() {
    var d = S.duell;
    if (!d || !d.uebung || !S.uebung) return;
    if (Date.now() > d.bis) { hinweis("⏱️ Übungsduell vorbei – unentschieden."); uebungEnde(); return; }
    var gegner = d.gegnerChat, ich = meineChatId();
    if (!platzElVon(gegner) || !platzElVon(ich)) { uebungEnde(); return; }
    var st = puppeStand(gegner);
    if (st.kaputt || S.uebung.lp <= 0) { puppeSchussPlanen(); return; }
    /* Ein zufälliger Punkt. Ganz gleichmäßig verteilt träfe die Puppe
       fast nur Rand und Körper — Kopf und Herz sind kleine Flächen, und
       man sähe kaum, ob sie zählen. Deshalb lost sie zuerst die ZONE
       (Kopf 25 %, Herz 15 %, Körper 35 %, Rand 15 %, daneben 10 %) und
       dann einen zufälligen Punkt darin. */
    var los = Math.random(), wunsch = los < 0.25 ? "kopf" : los < 0.4 ? "herz" : los < 0.75 ? "koerper" : los < 0.9 ? "streif" : "daneben";
    var dx = 0, dy = 0;
    for (var v = 0; v < 400; v++) {
      dx = Math.round((Math.random() * 2.3 - 1.15) * 100) / 100;
      dy = Math.round((Math.random() * 2.3 - 1.15) * 100) / 100;
      if (zoneRechnen(dx, dy) === wunsch) break;
    }
    var arten = ["zwille", "bogen", "laser", "armbrust", "tomahawk"];
    var waffe = arten[Math.floor(Math.random() * arten.length)];
    var farbe = LASERFARBEN[Math.floor(Math.random() * LASERFARBEN.length)];
    var nummer = meinPlatzNummer();
    var dauer = geschossZeigen(gegner, ich, waffe, dx, dy, farbe);
    setTimeout(function () {
      if (!S.uebung || !S.duell || !S.duell.uebung) return;
      if (meinPlatzNummer() !== nummer) { zahlZeigen(ich, null, "ausgewichen"); puppeSchussPlanen(); return; }
      var zone = zoneRechnen(dx, dy), schaden = schadenRechnen(waffe, zone);
      S.uebung.lp = Math.max(0, S.uebung.lp - schaden);
      trefferZeigen(ich, { zone: zone, schaden: schaden, abgewehrt: 0, kaputt: S.uebung.lp <= 0 });
      /* XANDER: „mein Drachen macht übrigens gar nix … wenn ich gegen den
         Sparring Partner kämpfe, sehe ich nicht, dass der … reagiert".
         Jetzt wehren sich die eigenen Tiere und der Turm auch in der
         Übung — gerechnet wie auf dem Server (spiel_treffer). */
      if (schaden > 0) {
        var gw = eigeneGegenwehr(schaden);
        if (gw.gegenwehr > 0 || gw.tier_heil > 0) {
          st.lp = Math.max(0, st.lp - gw.gegenwehr); st.kaputt = st.lp <= 0;
          if (gw.tier_heil > 0) S.uebung.lp = Math.min(S.uebung.max, S.uebung.lp + gw.tier_heil);
          gegenwehrZeigen(ich, gegner, gw);
        }
      }
      zeichnen();
      if (S.uebung.lp <= 0 || st.kaputt) {
        var ichVerloren = S.uebung.lp <= 0;
        hinweis(ichVerloren ? "💔 " + st.name + " hat die Runde gewonnen – weiter geht's." : "🏆 Runde gewonnen – " + st.name + " steht gleich wieder auf.");
        setTimeout(function () {
          if (!S.uebung) return;
          S.uebung.lp = S.uebung.max; st.lp = st.lp_max; st.kaputt = false;
          zeichnen(); puppeSchussPlanen();
        }, 2500);
        return;
      }
      puppeSchussPlanen();
    }, dauer);
  }

  /* ---------------------------------------------------------------
     SENDEN / EMPFANGEN über den Raumkanal
     --------------------------------------------------------------- */
  function senden(o) { try { var l = LC(); if (l && l.spielSenden) l.spielSenden(o); } catch (e) {} }

  function empfangen(n) {
    if (!n || !n.ereignis) return;
    if (n.stand && n.stand.id) S.stand[n.stand.id] = n.stand;
    if (n.ziel_stand && n.ziel_stand.id) S.stand[n.ziel_stand.id] = n.ziel_stand;
    if (n.ich_stand && n.ich_stand.id) S.stand[n.ich_stand.id] = n.ich_stand;
    /* Wer nicht mitspielt, bekommt nur den Stand – keine Bilder, keine Töne. */
    /* FASSUNG 669 — der Rundenkampf braucht kein „Mitspielen". */
    if (n.ereignis === "strat") { stratEmpfangen(n); return; }
    /* FASSUNG 682 — Spaßwaffen im Chat sehen ALLE (sie kosten nichts und zählen nichts). */
    if (n.ereignis === "chatwaffe") { chatWaffeZeigen(n); return; }
    if (!spielSichtbar() && n.ereignis !== "duell" && n.ereignis !== "duellnein") {
      /* FASSUNG 657 — nur ein freigegebenes Schaufenster (Level, Tiere) neu zeichnen. */
      if (n.ereignis === "stand" && n.stand && n.stand.zeigen) zeichnen();
      return;
    }
    if (n.ereignis === "schuss") {
      geschossZeigen(n.von, n.zielChat, n.waffe, n.dx, n.dy, n.farbe, Boolean(n.schnell), undefined, n.stufe);
    } else if (n.ereignis === "treffer") {
      trefferZeigen(n.zielChat, n);
      gegenwehrZeigen(n.zielChat, n.von, n);
      if (n.zielChat === meineChatId()) {
        /* Ich wurde getroffen — mein Stand kommt vom Server nach. */
        setTimeout(function () { abrufen(true); }, 300);
      }
    } else if (n.ereignis === "geschenk_ware") {
      /* FASSUNG 682 — jemand hat mir Ware geschenkt. */
      if (n.zielChat === meineChatId()) { ton("geschenk", 0.45); hinweis("🎁 " + (n.name || "Jemand") + " hat dir " + n.menge + " " + (WAREN[n.ware] || n.ware) + " geschenkt!"); abrufen(true); }
    } else if (n.ereignis === "gepluendert") {
      /* FASSUNG 683 — mein Gebäude wurde geplündert: es steht noch, ist nur beschädigt. */
      pluenderZeigen(n.zielChat, n.gebaeude);
      if (n.zielChat === meineChatId()) {
        ton("hammerschlag", 0.45);
        var weg = Object.keys(n.beute || {}).map(function (w) { return n.beute[w] + " " + (WAREN[w] || w); }).join(", ");
        hinweis("⚔️ " + (n.name || "Jemand") + " hat deine " + ((DORF[n.gebaeude] || {}).name || "Gebäude") + " geplündert" + (weg ? " (" + weg + ")" : "")
          + ". Sie steht noch – reparieren: Mein Dorf (1 Erz oder 2 Holz). Ritter schützen dich."
          + (n.rache ? "" : " Rache: 24 Stunden lang plünderst du " + (n.name || "ihn") + " einmal ohne Mana."));
        abrufen(true);
      } else if (spielSichtbar()) {
        /* FASSUNG 755 — „Das ganze Dorf sieht … wer geplündert hat": alle anderen im Raum lesen es mit. */
        hinweis("⚔️ " + (n.name || "Jemand") + (n.rache ? " rächt sich an " + (n.an || "?") + ": " : " plündert bei " + (n.an || "?") + ": ") + ((DORF[n.gebaeude] || {}).name || "ein Gebäude"));
      }
    } else if (n.ereignis === "pluender_abgewehrt") {
      /* FASSUNG 755 — der Plünderversuch ist gescheitert: Schild und Klang am Platz des Verteidigers, für alle. */
      abwehrZeigen(n.zielChat); ton("schildblock", 0.45);
      if (n.zielChat === meineChatId()) { hinweis("🛡️ Abgewehrt! " + (n.name || "Jemand") + " wollte deine " + ((DORF[n.gebaeude] || {}).name || "Gebäude") + " plündern – du bekommst " + (n.strafe || 0) + " Punkte."); abrufen(true); }
      else if (spielSichtbar()) hinweis("🛡️ " + (n.an || "?") + " hat einen Plünderversuch von " + (n.name || "?") + " abgewehrt");
    } else if (n.ereignis === "ausgewichen") {
      zahlZeigen(n.zielChat, null, "ausgewichen");
    } else if (n.ereignis === "heilung") {
      /* FUNK 108 — wer einen ANDEREN heilt, schickt dessen Platz mit;
         die grüne Zahl steigt dort auf, wo geheilt wurde. */
      zahlZeigen(n.zielChat || n.von, n.plus, n.zielChat && n.zielChat !== n.von ? "von " + (n.name || "") : "");
      ton("zauberpuff", 0.4);
      /* „sorte", nicht „art": spielSenden überschreibt „art" mit
         „spiel" (livechat.js) — so ging die Unterscheidung verloren. */
      if (n.sorte === "pflaster") { try { if (B().pflaster) B().pflaster(n.zielChat || n.von); } catch (e) {} }
    } else if (n.ereignis === "zauber") {
      zauberZeigen(n);
    } else if (n.ereignis === "zauberstart") {
      if (ZAUBER[n.sorte] && n.zielChat) zauberStart(n.sorte, n.von, n.zielChat, Math.max(250, Math.min(900, Number(n.flug) || 450)));
    } else if (n.ereignis === "faehigkeit") {
      if (FAEHIG[n.sorte]) faehigZeigen(n);
    } else if (n.ereignis === "kampfklasse") {
      if (KAMPF[n.sorte]) kampfZeigen(n);
    } else if (n.ereignis === "zauberab") {
      if (n.zielChat) zauberLanden(n.zielChat, true);
    } else if (n.ereignis === "falle") {
      falleZeigen(n.zielChat, n.sorte, n.schaden);
    } else if (n.ereignis === "essen") {
      ton("mampf", 0.4);
      zahlZeigen(n.von, n.plus, n.sorte === "bratwurst" ? "Bratwurst" : "Sauerkraut");
    } else if (n.ereignis === "daemon") {
      daemonAusbruch(n.von, false);
    } else if (n.ereignis === "trank") {
      if (n.sorte === "tarn") ton("tarnung", 0.5); else ton("trankschluck", 0.45);
    } else if (n.ereignis === "duell" && n.an === meineChatId()) {
      duellFrage(n);
    } else if (n.ereignis === "duellstart") {
      var ich = meineChatId();
      if (n.a === ich || n.b === ich) {
        var gegnerChat = n.a === ich ? n.b : n.a;
        S.duell = { id: n.id, gegner: spielIdVon(gegnerChat), gegnerChat: gegnerChat, bis: Date.now() + 180000 };
        hinweis("⚔️ Duell läuft! Tippe auf " + (n.a === ich ? n.bName : n.aName) + ", um zu treffen.");
        panelAuffrischen();
      }
    } else if (n.ereignis === "duellnein" && n.an === meineChatId()) {
      hinweis("🙅 " + (n.name || "Die Person") + " hat das Duell abgelehnt.");
    }
    zeichnen();
  }
  function meineChatId() { try { return LC().lage().ichId; } catch (e) { return ""; } }

  /* ---------------------------------------------------------------
     DER KAMPFMODUS: Antippen trifft — nur mit Waffe oder im Duell
     ---------------------------------------------------------------
     XANDER (Funk 90): „nur wenn wir in diesem Kampfmodus sind kann man
     wenn man auf die Profilbilder klickt denjenigen direkt treffen dann
     tauschen sich die Plätze nicht aus sondern man trifft direkt und je
     nachdem wo man hinzielt auf den Winkel vom Profilbild desto viel
     Punkte kriegt man auch … und wenn wir nicht in diesem Kampfmodus sind
     … tauscht einfach nur die Plätze aus." */
  function imDuellMit(chatId) {
    if (!S.duell) return false;
    if (Date.now() > S.duell.bis) { S.duell = null; return false; }
    return S.duell.gegnerChat === chatId;
  }
