        turm.style.setProperty("--zielwinkel", (Math.atan2(z.y - sy, z.x - sx) * 180 / Math.PI).toFixed(1) + "deg");
        void dreh.getBoundingClientRect();
        if (spitze) { var sr = spitze.getBoundingClientRect(); if (sr.width >= 0 && sr.left) { sx = sr.left + sr.width / 2; sy = sr.top + sr.height / 2; } }
