    var gruppen = RAD_KLASSEN.map(function (k) { return { name: k[0], farbe: k[1], waffen: k[2].filter(hat) }; }).filter(function (g) { return g.waffen.length; });
    var n = 0; gruppen.forEach(function (g) { n += g.waffen.length; });
