          + '" style="left:' + (p[0] - 20) + "px;top:" + (p[1] - 20) + "px;--klasse:" + g.farbe + '" title="' + esc(WAFFEN[w].name + " · " + g.name) + '">'
          + geschossSvg(w, S.laserfarbe) + "<small>" + (vr >= 0 ? "×" + vr : WAFFEN[w].schaden) + "</small>"
          + (s[nr] === w ? '<i class="sp-haken"><svg viewBox="0 0 10 10"><path d="M2 5.2 L4.2 7.4 L8 2.8" fill="none" stroke="#1d2330" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg></i>' : "") + "</button>";
