    return '<svg viewBox="0 0 24 24"><rect x="3" y="5" width="18" height="14" rx="1.6" fill="#8a5a2e" stroke="#4d3016" stroke-width="1.2"/><path d="M9 5 V19 M15 5 V19" stroke="#4d3016" stroke-width="1"/>'
