      aussen += '<button type="button" class="sp-rad-waffe sp-ring-feld' + (an ? " sp-an sp-angelegt" : "") + (offen ? " sp-ring-auf" : "") + (haltVon(ich, d) === 0 ? " sp-stumpf" : "")
        + '" data-s="ringbereich" data-b="' + b[0] + '" data-w="' + d + '" style="left:' + (q[0] - 18).toFixed(0) + "px;top:" + (q[1] - 18).toFixed(0) + "px;--klasse:" + b[2]
        + '" title="' + esc(b[1] + ": " + (RING_FALLE[d] ? RING_FALLE[d].name : WAFFEN[d] ? WAFFEN[d].name : "")) + '">' + ringDingSvg(d) + "<small>" + zahl + "</small>"
        + (mehr > 1 ? '<i class="sp-ring-mehr">' + mehr + "</i>" : "")
