        + '<button type="button" data-s="graben" data-w="schaufel" class="' + (S.graben && S.werkzeug === "schaufel" ? "sp-an" : "") + '">' + (S.graben && S.werkzeug === "schaufel" ? "Schaufel weglegen" : "Graben (Schaufel)") + " <small>" + vorrat(ich, "erz") + " Erz</small></button>"
