        + '<path class="sp-fluegel-r" d="M98 17 C106 8 112 13 110 20 C107 18 105 21 102 20 C101 22 99 21 98 20 Z" fill="#9fdcc0" stroke="#3c8a6a" stroke-width=".9"/>'
        + '<path d="M96 25 C102 27 103 22 100 20" fill="none" stroke="#5cb892" stroke-width="2.2" stroke-linecap="round"/><path d="M100 19.4 l1.6 -1.6 l.4 2.4 z" fill="#f59ab4"/>'
        + '<ellipse cx="90" cy="22" rx="7" ry="5.4" fill="#6fcaa0" stroke="#3c8a6a" stroke-width=".9"/>'
        + '<ellipse cx="90" cy="23" rx="4" ry="3.2" fill="#fbeab8"/>'
        + '<path d="M85 5.5 L84 1.5 L87.6 4.2 Z M95 5.5 L96 1.5 L92.4 4.2 Z" fill="#fbeab8" stroke="#c9a86a" stroke-width=".5"/>'
        + '<circle cx="90" cy="12" r="8.6" fill="#6fcaa0" stroke="#3c8a6a" stroke-width="1"/>'
