        + '<ellipse cx="84.4" cy="14.6" rx="1.6" ry="1" fill="#f59ab4" opacity=".8"/><ellipse cx="95.6" cy="14.6" rx="1.6" ry="1" fill="#f59ab4" opacity=".8"/>'
        + '<path d="M88.4 15.2 Q90 16.6 91.6 15.2" fill="none" stroke="#2c5a46" stroke-width=".8" stroke-linecap="round"/>'
