    if (tu === "anlegen") { S.waffe = k.dataset.w; hinweis("🎯 " + WAFFEN[S.waffe].name + " angelegt – tippe auf ein Gesicht."); schliessen(); zeichnen(); return; }
    if (tu === "ablegen") { S.waffe = ""; zeichnen(); panelAuffrischen(); return; }
