      var kopf = '<button type="button" data-s="kaufwahl" data-w="' + x + '" class="sp-markt-ware' + (offen ? " sp-an" : "") + '">' + wareSvg(x) + WAREN[x] + " <small>"
        + ek + " P je Stück · du hast " + hat + (voll ? " · Lager voll" : "") + " " + (offen ? "▴" : "▾") + "</small></button>";
