  function ausflugBis(ich) { var t = Date.parse((((ich || {}).volk) || {}).ausflug_bis || ""); return t > Date.now() ? t : 0; }
  function ausflugFreude(ich) { return ausflugBis(ich) ? 5 : 0; }
