    var BALLEN = [[0, 0, 1, 1], [-.42, .18, .74, .8], [.45, .24, .7, .75]];
    while (kreise.length < 34 * 3) { var k = document.createElementNS("http://www.w3.org/2000/svg", "circle"); k.setAttribute("r", "0"); ebene.appendChild(k); }
    BAHN.puffs = BAHN.puffs.filter(function (p) { return jetzt - p.t < (p.art === "zylinder" ? 1.1 : p.art === "leise" ? 2.2 : 3.2); });
    while (BAHN.puffs.length > 34) BAHN.puffs.shift();
    /* Kein Rauch mehr und schon alles gelöscht: die 102 Ballen nicht jedes Bild wieder anfassen. */
    var leer = !BAHN.puffs.length;
    for (var j = 0; j < (leer && BAHN.rauchLeer ? 0 : 34); j++) {
      var p = BAHN.puffs[j];
      for (var bi = 0; bi < 3; bi++) {
        var e2 = kreise[j * 3 + bi];
        if (!p) { if (e2.getAttribute("r") !== "0") e2.setAttribute("r", "0"); continue; }
        var a2 = jetzt - p.t, leben = p.art === "zylinder" ? 1.1 : p.art === "leise" ? 2.2 : 3.2, rest = 1 - a2 / leben, Bb = BALLEN[bi];
        var x2 = p.art === "zylinder" ? p.x - 3.2 * a2 + p.dx : p.x + (1.4 + p.dx) * a2, y2 = p.art === "zylinder" ? p.y - .6 * a2 : p.y - (7.2 * a2 - 1.2 * a2 * a2);
        var r2 = p.art === "zylinder" ? .6 + 2.2 * Math.sqrt(a2) : p.art === "leise" ? .45 + 1.7 * Math.sqrt(a2) : .8 + 3.1 * Math.sqrt(a2);
        /* Die Nebenballen treiben mit dem Alter etwas auseinander. */
        var ausein = 1 + a2 * .5;
        e2.setAttribute("cx", (x2 + Bb[0] * r2 * ausein).toFixed(2)); e2.setAttribute("cy", (y2 + Bb[1] * r2 * ausein).toFixed(2)); e2.setAttribute("r", (r2 * Bb[2]).toFixed(2));
        e2.setAttribute("fill", p.art === "russ" && bi === 0 ? "url(#spBzRuss)" : "url(#spBzDampf)");
        e2.setAttribute("opacity", (Math.pow(Math.max(0, rest), 1.3) * Bb[3] * (p.art === "leise" ? .6 : p.art === "zylinder" ? .9 : 1)).toFixed(3));
      }
    }
    BAHN.rauchLeer = leer;
