    return '<div class="sp-bahn-kurtaxe"><div class="sp-bahn-bel"><b>Beliebtheit ' + (b.wert || 0) + '</b><i class="sp-dipl-balken"><u style="width:' + Math.max(0, Math.min(100, b.wert || 0)) + '%;background:#e2a93a"></u></i>'
      + '<small>Grundwert 10' + (teile.length ? " · " + teile.join(" · ") : "") + "</small></div>"
      + '<div class="sp-bahn-taxe"><span>Kurtaxe je Gast</span><button type="button" data-s="kurtaxe" data-n="-1"' + (t.taxe <= 1 ? " disabled" : "") + ' aria-label="Kurtaxe senken">−</button><b>' + t.taxe + " P</b>"
