      var p = pk[2 + Math.floor(Math.random() * (n - 4))], wi = Math.atan2(dy, dx) + (Math.random() < .5 ? -1 : 1) * (.4 + Math.random() * .5), l = L * (.18 + Math.random() * .2);
      d += " " + dwBlitzFlaeche(p[0], p[1], p[0] + Math.cos(wi) * l, p[1] + Math.sin(wi) * l, breite(p[2]) * .55, tiefe ? 1 : 2, tiefe + 1);
