        for (var i = 0; i < len; i++) { var wn = Math.random() * 2 - 1; last = (last + .02 * wn) / 1.02; dat[i] = wn * .55 + last * 3.2; }
        var q = k.createBufferSource(); q.buffer = buf; q.loop = true;
