            + (a.eigen ? '<button type="button" data-s="angebotweg" data-id="' + a.id + '">Zurückziehen</button>'
                       : '<button type="button" data-s="angebotkauf" data-id="' + a.id + '" data-n="' + a.menge + '"' + ((ich.punkte || 0) >= a.preis * a.menge ? "" : " disabled") + ">Kaufen · " + a.preis * a.menge + "</button>")
