    if (vorrat(S.ich, "duenger") < 1) { hinweis("🧪 Kein Dünger – im Dorf-Menü (Handel) kaufen, beim Händler oder billiger bei Mitspielern."); return; }
    saatZeigen(knopf);
    ton("platsch", 0.3);
    rpc("spiel_duengen", { p_platz: nr }).then(function (r) {
      if (!r || !r.ok) { hinweis("🧪 " + ((r && r.grund) || "geht nicht")); return; }
      if (r.id) { S.ich = r; S.stand[r.id] = oeffentlich(r); }
      hinweis("🧪 Gedüngt – das Feld ist zwei Minuten früher reif.");
      ackerPflegen(); schnellZeichnen();
    }).catch(function () { hinweis("🧪 Das ging gerade nicht."); });
