    if (laut === "au") return '<svg viewBox="-12 -12 24 24"><path d="M0 -10 L2.6 -3.4 L9.6 -4.6 L4.6 0.6 L8.4 7.6 L1.2 4.6 L-3.2 10 L-3 3 L-10 1.4 L-4 -2.2 L-6.6 -8.6 L-1 -4.4 Z" fill="#ffd23a" stroke="#e2403a" stroke-width="1.4" stroke-linejoin="round"/></svg>';
