    var tiere = [].slice.call(platz.querySelectorAll(".sp-tier, .sp-flugtier")).filter(function (t) { return !t.classList.contains("sp-tier-schwach"); });
    if (!tiere.length) return "";
    /* Die alten Namen aus Fassung 682 gelten weiter. */
    if (art === "sahne") art = "schlecken";
