    if (ST.gegner === "computer") { if (schaden) stratTreffer("er", schaden, ak === "super"); stratEndePruefen(); stratZeigen(); if (!ST.ende && ST.modus === "zug") setTimeout(stratComputer, 1300); return; }
    /* Das Bild des Einschlags sofort (die echten Zahlen kommen mit der Quittung). */
